// backends/pi/resources-extension.js — ONE per-spawn extension for what a Pi session is given (#632, O5).
//
// Two things a session can be given here live in one generated file, as sections:
//   - the `subagent` tool (#634, `./subagent-tool.js`), when the `subagentTool` option is on;
//   - another CLI's commands (#632, `./command-bridge.js`), when a source is chosen and offers commands;
//   - another CLI's MCP servers (#633, `./mcp-section.js`), when their toggle is on and the source has any;
//   - another CLI's hooks (#635, `./hooks-section.js`), run on this session's own lifecycle events, when
//     their toggle is on and the source has any this target can place.
// One file, one `--extension`, one release — and the place #633 (MCP tools) and #635 (lifecycle commands)
// attach their sections, instead of each growing a hook pair and a file of its own.
//
// Each section brings the imports it needs; they are merged here, because an import written twice in one
// module is an error, and a section must not have to know which others it shares a file with.
//
// A raw `fs.writeFileSync` is right here for the reason `prompt-templates.js` gives: the file is made fresh
// for this spawn under the app's own data directory, and nothing else writes it.
'use strict';

const fs = require('fs');
const path = require('path');

const subagentTool = require('./subagent-tool');
const commandBridge = require('./command-bridge');
const mcpSection = require('./mcp-section');
const hooksSection = require('./hooks-section');
const promptTemplates = require('./prompt-templates');

// The tag becomes part of a file name, and `removeResourcesExtension` deletes a file by that name.
const SAFE_TAG = /^[A-Za-z0-9][A-Za-z0-9_-]{0,127}$/;
const FILE_PREFIX = 'pi-resources-';
const OWN_FILE = new RegExp(`^${FILE_PREFIX}[A-Za-z0-9][A-Za-z0-9_-]{0,127}\\.ts$`);

/** Merge import lines: named imports from one module become one line; anything else is kept once. */
function mergeImports(lines) {
  const named = new Map();
  const other = [];
  for (const line of lines) {
    const m = /^import \{([^}]*)\} from ("[^"]+");$/.exec(line.trim());
    if (m) {
      const names = named.get(m[2]) || new Set();
      for (const n of m[1].split(',').map((s) => s.trim()).filter(Boolean)) names.add(n);
      named.set(m[2], names);
    } else if (!other.includes(line.trim())) {
      other.push(line.trim());
    }
  }
  const merged = [...named].map(([mod, names]) => `import { ${[...names].sort().join(', ')} } from ${mod};`);
  return [...other, ...merged];
}

/**
 * The extension's text for these sections, or '' when there is nothing to give.
 * `subagent`: `{ agentsDir, sourceAgents }` or null (`sourceAgents`: another CLI's agent directories, #639). `commands`: the core's resolved command directories, or [].
 * `mcp`: true when MCP servers are handed over (#633) — WHICH ones travel in the environment, not in this text.
 */
function extensionSource({ subagent = null, commands = [], mcp = false, hooks = [] } = {}) {
  const imports = [];
  const sections = [];
  const calls = [];
  if (subagent) {
    imports.push(...subagentTool.IMPORTS);
    sections.push(subagentTool.subagentSection(subagent));
    calls.push('registerSubagent(pi);');
  }
  if (commands && commands.length) {
    imports.push(...commandBridge.IMPORTS);
    sections.push(commandBridge.commandSection({ commands, ownTemplatePrefix: promptTemplates.DIR_PREFIX }));
    calls.push('registerSourceCommands(pi);');
  }
  if (mcp) {
    imports.push(...mcpSection.IMPORTS);
    sections.push(mcpSection.mcpSection());
    calls.push('registerMcpServers(pi);');
  }
  if (hooks && hooks.length) {
    const text = hooksSection.hooksSection(hooks);
    if (text) {
      imports.push(...hooksSection.IMPORTS);
      sections.push(text);
      calls.push('registerSourceHooks(pi);');
    }
  }
  if (!sections.length) return '';
  return '// Generated by Switchboard for one Pi spawn. Safe to delete.\n'
    + mergeImports(imports).join('\n') + '\n\n'
    + sections.join('\n')
    + '\nexport default function (pi: any) {\n' + calls.map((c) => '  ' + c).join('\n') + '\n}\n';
}

/**
 * Write the extension for one spawn, or decline. `{ file }` or null — null for anything it cannot or will
 * not do, because a launch must never fail over this.
 */
function writeResourcesExtension({ dir, tag, subagent, commands, mcp, hooks, log } = {}) {
  if (!dir || !tag || !SAFE_TAG.test(String(tag))) return null;
  const text = extensionSource({ subagent, commands, mcp, hooks });
  if (!text) return null;
  const file = path.join(dir, `${FILE_PREFIX}${tag}.ts`);
  try {
    fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(file, text, 'utf8');
  } catch (err) {
    if (log && typeof log.warn === 'function') log.warn(`[pi-resources] could not write the extension: ${err.message}`);
    return null;
  }
  if (log && typeof log.debug === 'function') log.debug('[pi-resources] extension written for one spawn');
  return { file };
}

/** Remove a file this module wrote, and nothing else. */
function removeResourcesExtension(file, log) {
  if (!file || !OWN_FILE.test(path.basename(String(file)))) return;
  try { fs.rmSync(file, { force: true }); }
  catch (err) { if (log && typeof log.warn === 'function') log.warn(`[pi-resources] cleanup failed: ${err.message}`); }
}

module.exports = { FILE_PREFIX, mergeImports, extensionSource, writeResourcesExtension, removeResourcesExtension };
